using System;using System.Data.SqlClient;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.Services{public static class AuthService{public static bool Login(string username,string password,out string error){error=null;var t=Database.Query("SELECT TOP 1 * FROM Users WHERE Username=@u",new SqlParameter("@u",username.Trim()));if(t.Rows.Count==0){error=L.Fa?"نام کاربری یا رمز عبور صحیح نیست.":"Invalid username or password.";return false;}var r=t.Rows[0];if(!(bool)r["IsActive"]){error=L.Fa?"حساب کاربری غیرفعال است.":"This account is disabled.";return false;}if(Security.Hash(password,r["Salt"].ToString())!=r["PasswordHash"].ToString()){error=L.Fa?"نام کاربری یا رمز عبور صحیح نیست.":"Invalid username or password.";return false;}AppSession.UserId=(int)r["Id"];AppSession.Username=r["Username"].ToString();AppSession.FullName=r["FullName"].ToString();AppSession.Role=r["Role"].ToString();Database.Audit("Login","Session",AppSession.Username);return true;}public static bool Register(string full,string user,string email,string pass,out string error){error=null;if(string.IsNullOrWhiteSpace(full)||string.IsNullOrWhiteSpace(user)||!Security.Strong(pass)){error=L.Fa?"نام، نام کاربری و رمز حداقل ۸ کاراکتری الزامی است.":"Name, username and an 8+ character password are required.";return false;}try{var salt=Security.Salt();Database.Exec("INSERT Users(Username,PasswordHash,Salt,FullName,Email,Role) VALUES(@u,@p,@s,@f,@e,'Candidate')",new SqlParameter("@u",user.Trim()),new SqlParameter("@p",Security.Hash(pass,salt)),new SqlParameter("@s",salt),new SqlParameter("@f",full.Trim()),new SqlParameter("@e",email??""));return true;}catch(SqlException){error=L.Fa?"این نام کاربری قبلاً ثبت شده است.":"Username already exists.";return false;}}}}